<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {api,useAccount,run,notify,yuan,date,statuses,refundStatuses,upload} from '../lib'
import OrderPanel from '../components/OrderPanel.vue'
const route=useRoute(),router=useRouter(),account=useAccount(),section=computed(()=>route.params.section||'overview'),page=ref(1),data=ref({items:[],total:0}),q=ref(''),status=ref(-1),rating=ref(0),warning=ref(false),categories=ref([]),overview=ref({}),trend=ref([]),loading=ref(false),busy=ref(false),productOpen=ref(false),product=ref({images:[]}),stockOpen=ref(false),stockForm=ref({}),selectedOrder=ref(null),dateStart=ref(''),dateEnd=ref(''),selectedUser=ref(null)
const menus=[['overview','经营概览','chart'],['products','商品管理','flower'],['images','图片管理','edit'],['stock','库存管理','box'],['stock-records','库存记录','edit'],['orders','订单管理','bag'],['refunds','退款管理','back'],['reviews','评价管理','star'],['revenue','账单汇总','chart'],['users','用户管理','user'],['logs','操作日志','edit']]
const title=computed(()=>menus.find(i=>i[0]===section.value)?.[1]||'经营概览')
const chart=computed(()=>{let days=Array.from({length:30},(_,i)=>{let d=new Date();d.setDate(d.getDate()-29+i);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')});let map=Object.fromEntries(trend.value.map(t=>[String(t.day).slice(0,10),Number(t.amount)]));let values=days.map(d=>map[d]||0),max=Math.max(...values,1);return {days,values,max,points:values.map((v,i)=>`${10+i*24},${170-v/max*140}`).join(' ')}})
async function load(){loading.value=true;try{if(section.value==='overview'){let results=await Promise.all([api.get('/admin/statistics/overview'),api.get('/admin/statistics/trend')]);overview.value=results[0];trend.value=results[1]}else{let url={products:'/admin/products',images:'/admin/media',stock:warning.value?'/admin/stock/warning':'/admin/stock/list','stock-records':'/admin/stock/records',orders:'/admin/orders',refunds:'/admin/refunds',reviews:'/admin/reviews',revenue:'/admin/statistics/revenue',users:'/admin/users',logs:'/admin/audit-logs'}[section.value];if(!url)return router.replace('/admin');data.value=await api.get(url,{params:{page:page.value,q:q.value,status:status.value,rating:rating.value,start:dateStart.value,end:dateEnd.value}})}}finally{loading.value=false}}
function filter(){page.value=1;run(load)}
watch(section,()=>{page.value=1;q.value='';status.value=-1;data.value={items:[],total:0};run(load)})
onMounted(()=>run(async()=>{categories.value=await api.get('/category/list');await load()}))
async function editProduct(p){if(p){let r=await api.get('/admin/product/'+p.id);product.value={...r,images:r.images.filter(i=>i.image_type==='detail').map(i=>i.image_url)}}else product.value={name:'',price:199,category_id:categories.value[0]?.id,description:'',specification:'',cover:'/images/bouquet-1.svg',images:[],stock:0,warning_stock:10,status:0};productOpen.value=true}
async function saveProduct(){if(busy.value)return;busy.value=true;try{let p=product.value;await api[p.id?'put':'post'](p.id?'/admin/product/'+p.id:'/admin/product',p);notify('商品已保存');productOpen.value=false;await load()}finally{busy.value=false}}
async function productPhotos(e,cover){let files=[...e.target.files];e.target.value='';if(!cover&&files.length+product.value.images.length>9)return notify('详情图片最多9张');busy.value=true;try{for(let f of files){let img=await upload(f,'product');if(cover){product.value.cover=img.url;break}else product.value.images.push(img.url)}}finally{busy.value=false}}
async function toggle(p){await api.put('/admin/product/'+p.id+'/status',{status:p.status===1?0:1});notify('销售状态已更新');await load()}
async function removeProduct(p){await ElMessageBox.confirm('逻辑删除后商城不再展示，历史订单和图片引用仍保留。','删除商品');await api.delete('/admin/product/'+p.id);await load()}
function stockEdit(p){stockForm.value={product_id:p.id,name:p.name,current:p.stock,type:'add',quantity:1,remark:''};stockOpen.value=true}
async function saveStock(){if(busy.value)return;busy.value=true;try{await api.put('/admin/stock/'+stockForm.value.type,stockForm.value);notify('库存已更新并记录日志');stockOpen.value=false;await load()}finally{busy.value=false}}
async function refundAction(r,approve){let body={};if(approve)await ElMessageBox.confirm('同意后由后端模拟处理，最多约5秒更新结果。','同意模拟退款');else{let {value}=await ElMessageBox.prompt('请填写明确的拒绝原因。','拒绝退款',{inputValidator:v=>!!v?.trim()||'请填写原因'});body.reason=value}await api.put('/admin/refund/'+(approve?'approve':'reject')+'/'+r.id,body);notify(approve?'已进入退款处理中，请稍后刷新':'已拒绝退款');await load()}
async function reply(r){let {value}=await ElMessageBox.prompt('回复用户的这份心意。','回复评价',{inputValue:r.reply||'',inputValidator:v=>!!v?.trim()||'请填写回复内容'});await api.post('/admin/review/'+r.id+'/reply',{content:value});notify('回复已保存');await load()}
async function moderate(r){let {value}=await ElMessageBox.prompt('请填写具体处理依据，此操作会保留审核日志。','评价'+(r.status?'隐藏':'恢复'),{inputValidator:v=>!!v?.trim()||'必须填写处理依据'});await api.put('/admin/review/'+r.id+'/status',{status:r.status?0:1,reason:value});await load()}
async function userStatus(u){await ElMessageBox.confirm(u.status?'禁用后该用户已有令牌失效，不能继续执行登录操作。':'恢复此用户账号？','账号状态');await api.put('/admin/user/status/'+u.id,{status:u.status?0:1});await load()}
async function userDetail(u){selectedUser.value=await api.get('/admin/user/'+u.id)}
function moveImage(i,delta){let j=i+delta;if(j<0||j>=product.value.images.length)return;[product.value.images[i],product.value.images[j]]=[product.value.images[j],product.value.images[i]]}
</script>
<template><div class="admin-app"><aside class="admin-sidebar"><RouterLink to="/admin" class="brand"><Icon name="flower" :size="32"/><span>花礼 <b>FLEUR</b><small>MERCHANT STUDIO</small></span></RouterLink><span class="admin-menu-label">花店工作台</span><RouterLink v-for="m in menus" :key="m[0]" :to="'/admin/'+m[0]" :class="{active:section===m[0]}"><Icon :name="m[2]" :size="19"/>{{m[1]}}<span v-if="m[0]==='orders'&&overview.pending" class="sidebar-count">{{overview.pending}}</span></RouterLink><div class="admin-sidebar-bottom"><RouterLink to="/"><Icon name="arrow" :size="18"/> 前往商城</RouterLink><button @click="account.logout('admin');router.push('/admin/login')"><Icon name="logout" :size="18"/> 退出登录</button></div></aside><div class="admin-main"><header class="admin-topbar"><span>商家工作台 <small>/ {{title}}</small></span><div><span class="live-dot"></span>本地图片存储 <span class="admin-avatar">掌</span>{{account.admin?.nickname||'花礼掌柜'}}</div></header><div class="admin-content"><div class="admin-page-heading"><div><span class="eyebrow">FLEUR MERCHANT STUDIO</span><h1>{{section==='overview'?'今日，也要用心经营。':title}}</h1><p>{{section==='overview'?'从每一份订单开始，让美好生意慢慢生长。':'每一份心意，都值得被认真对待。'}}</p></div><div class="admin-heading-actions"><button class="btn small" @click="run(load)"><Icon name="back" :size="15"/> 刷新数据</button><button v-if="section==='products'" class="btn primary small" @click="run(()=>editProduct())">+ 新增商品</button></div></div><div class="admin-notice"><Icon name="leaf" :size="17"/><span>模拟经营环境 · 支付、退款均为流程测试，以下统计不代表真实资金流水。</span></div><div v-if="section==='overview'" v-loading="loading"><div class="metric-grid"><div v-for="(c,i) in [['今日营业额',overview.today_revenue,'¥','今日模拟支付成功金额'],['本月营业额',overview.month_revenue,'¥','本月模拟支付成功金额'],['待接单订单',overview.pending,'','等待你送出一份心意'],['可售库存预警',overview.low_stock,'','缺货 '+(overview.sold_out||0)+' 款'] ]" :key="c[0]" class="metric-card"><div class="row-between"><span>{{c[0]}}</span><Icon :name="['chart','bag','box','leaf'][i]"/></div><strong><small>{{c[2]}}</small>{{c[2]?yuan(c[1]):c[1]||0}}</strong><small>{{c[3]}}</small></div></div><div class="dashboard-grid"><div class="panel trend-panel"><div class="row-between"><h3>销售趋势 <small>近30天模拟收款</small></h3><span class="chart-legend">支付成功金额</span></div><div class="trend-chart"><span class="chart-max">¥ {{yuan(chart.max)}}</span><svg viewBox="0 0 720 190" role="img" aria-label="近30天模拟支付成功金额趋势图"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#748b76" stop-opacity=".3"/><stop offset="1" stop-color="#748b76" stop-opacity="0"/></linearGradient></defs><path d="M10 30H710 M10 100H710 M10 170H710" stroke="#eaece6" stroke-dasharray="4 4"/><polygon :points="'10,170 '+chart.points+' 706,170'" fill="url(#area)"/><polyline :points="chart.points" fill="none" stroke="#66816b" stroke-width="2.5"/><circle v-for="(v,i) in chart.values" :key="i" :cx="10+i*24" :cy="170-v/chart.max*140" r="2" fill="#66816b"><title>{{chart.days[i]}}：¥{{yuan(v)}}</title></circle></svg><div class="chart-dates"><span>{{chart.days[0]}}</span><span>无交易日期按0显示</span><span>{{chart.days[29]}}</span></div></div></div><div class="panel quick-panel"><span class="eyebrow">TODAY'S TO-DO</span><h3>花店待办</h3><RouterLink to="/admin/orders"><span><Icon name="bag"/> 待接订单</span><b>{{overview.pending||0}} <Icon name="arrow" :size="15"/></b></RouterLink><RouterLink to="/admin/refunds"><span><Icon name="back"/> 待审退款</span><b>{{overview.pending_refunds||0}} <Icon name="arrow" :size="15"/></b></RouterLink><RouterLink to="/admin/stock"><span><Icon name="box"/> 库存预警</span><b>{{overview.low_stock||0}} <Icon name="arrow" :size="15"/></b></RouterLink><div class="shop-note"><Icon name="flower" :size="28"/><p>鲜花有时，心意无期。<br>今天也要照顾好每一份期待。</p></div></div></div><div class="dashboard-grid"><div class="panel"><div class="row-between"><h3>花礼人气榜 <small>按已支付商品数量</small></h3><RouterLink to="/admin/products" class="text-link">查看商品 <Icon name="arrow" :size="15"/></RouterLink></div><div v-for="(r,i) in overview.ranking" :key="r.product_id" class="ranking-row"><span>0{{i+1}}</span><strong>{{r.name}}</strong><span>{{r.quantity}} 束</span><b>¥{{yuan(r.amount)}}</b></div><div v-if="!overview.ranking?.length" class="empty">暂无已支付订单，期待第一份花礼。</div></div><div class="panel ledger-overview"><h3>经营账本</h3><div class="row-between"><span>累计模拟收款</span><b>¥ {{yuan(overview.revenue)}}</b></div><div class="row-between"><span>累计成功退款</span><b>¥ {{yuan(overview.refunded)}}</b></div><div class="row-between"><span>实际模拟净收款</span><strong>¥ {{yuan(overview.net)}}</strong></div><p>今日 {{overview.today_orders||0}} 单 · 本月 {{overview.month_orders||0}} 单</p><p>已完成 {{overview.completed||0}} 单 · 评价 {{overview.reviews||0}} 条 · 均分 {{Number(overview.rating||0).toFixed(1)}}</p></div></div></div><div v-else class="panel admin-data-panel" v-loading="loading"><div class="admin-toolbar"><form @submit.prevent="filter" class="search-field" v-if="['products','stock','orders','reviews','users'].includes(section)"><Icon name="search" :size="17"/><input v-model="q" :placeholder="section==='orders'?'搜索订单编号':section==='users'?'昵称 / 手机号 / 账号':'搜索商品名称'"/><button class="text-button">搜索</button></form><select v-if="section==='orders'" v-model="status" @change="filter"><option :value="-1">全部订单状态</option><option v-for="(s,i) in statuses" :key="i" :value="i">{{s}}</option></select><select v-if="section==='reviews'" v-model="rating" @change="filter"><option :value="0">全部评分</option><option v-for="i in 5" :key="i" :value="i">{{i}}星</option></select><label class="checkbox-label" v-if="section==='stock'"><input type="checkbox" v-model="warning" @change="filter"/> 仅看库存预警</label><template v-if="section==='revenue'"><label>开始日期 <input type="date" v-model="dateStart"/></label><label>结束日期 <input type="date" v-model="dateEnd"/></label><button class="btn small" @click="filter">筛选账单</button></template><span class="subtle">共 {{data.total}} 条记录</span></div><template v-if="section==='products'"><el-table :data="data.items" row-key="id"><el-table-column label="商品" min-width="260"><template #default="{row}"><div class="table-product"><img :src="row.cover" :alt="row.name"/><div><b>{{row.name}}</b><p>{{row.specification}}</p></div></div></template></el-table-column><el-table-column prop="category_name" label="分类" width="110"/><el-table-column label="售价" width="100"><template #default="{row}">¥{{yuan(row.price)}}</template></el-table-column><el-table-column prop="stock" label="可售库存" width="95"/><el-table-column label="销售状态" width="100"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'已上架':'已下架'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="190"><template #default="{row}"><button class="text-button" @click="run(()=>editProduct(row))">编辑</button><button class="text-button" @click="run(()=>toggle(row))">{{row.status?'下架':'上架'}}</button><button class="text-button muted" @click="run(()=>removeProduct(row))">删除</button></template></el-table-column></el-table></template><template v-else-if="section==='stock'"><el-alert title="这里调整的是可售库存；已下单的预留库存已被扣除。已制作花束退款不会自动恢复库存。" type="info" :closable="false"/><el-table :data="data.items"><el-table-column prop="name" label="花束名称" min-width="220"/><el-table-column prop="stock" label="可售库存"/><el-table-column prop="warning_stock" label="预警阈值"/><el-table-column label="库存状态"><template #default="{row}"><el-tag :type="row.stock===0?'danger':row.stock<=row.warning_stock?'warning':'success'">{{row.stock===0?'缺货':row.stock<=row.warning_stock?'库存预警':'充足'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><button class="text-button" @click="stockEdit(row)">调整库存</button><button class="text-button" @click="run(()=>editProduct(row))">设置阈值</button></template></el-table-column></el-table></template><template v-else-if="section==='stock-records'"><el-table :data="data.items"><el-table-column prop="name" label="商品" min-width="200"/><el-table-column prop="change_type" label="类型"/><el-table-column prop="change_quantity" label="变动"/><el-table-column prop="before_stock" label="原库存"/><el-table-column prop="after_stock" label="新库存"/><el-table-column prop="remark" label="说明" min-width="180"/><el-table-column label="时间" min-width="165"><template #default="{row}">{{date(row.create_time)}}</template></el-table-column></el-table></template><template v-else-if="section==='orders'"><el-table :data="data.items"><el-table-column prop="order_no" label="订单编号" min-width="210" show-overflow-tooltip/><el-table-column prop="nickname" label="用户" width="105"/><el-table-column label="金额" width="110"><template #default="{row}">¥{{yuan(row.total)}}</template></el-table-column><el-table-column label="状态" width="115"><template #default="{row}"><span class="status-tag" :class="'status-'+row.status">{{statuses[row.status]}}</span></template></el-table-column><el-table-column label="下单时间" width="175"><template #default="{row}">{{date(row.create_time)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><button class="text-button" @click="selectedOrder=row.id">查看 / 处理</button></template></el-table-column></el-table></template><template v-else-if="section==='refunds'"><el-alert title="同意后进入处理中，由后端每5秒执行模拟退款；失败可重试，不会重复退回。" type="info" :closable="false"/><el-table :data="data.items"><el-table-column prop="refund_no" label="退款编号" min-width="170" show-overflow-tooltip/><el-table-column label="退款金额" width="110"><template #default="{row}">¥{{yuan(row.refund_amount)}}</template></el-table-column><el-table-column label="原因 / 说明" min-width="190"><template #default="{row}">{{row.refund_reason}}<p>{{row.refund_remark}}</p><p class="danger">{{row.reject_reason||row.fail_reason}}</p></template></el-table-column><el-table-column label="状态" width="115"><template #default="{row}"><el-tag :type="row.refund_status===3?'success':row.refund_status===5?'danger':'warning'">{{refundStatuses[row.refund_status]}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{row}"><button class="text-button" @click="selectedOrder=row.order_id">查看订单</button><template v-if="[1,5].includes(row.refund_status)"><button class="text-button" @click="run(()=>refundAction(row,true))">{{row.refund_status===5?'重试退款':'同意'}}</button><button class="text-button muted" v-if="!row.auto_cancel" @click="run(()=>refundAction(row,false))">拒绝</button></template></template></el-table-column></el-table></template><template v-else-if="section==='reviews'"><article class="admin-review" v-for="r in data.items" :key="r.id"><div class="row-between"><div><b>{{r.product_name}}</b> · {{r.nickname}} <span class="rating">{{'★'.repeat(r.rating)}}</span></div><el-tag :type="r.status?'success':'info'">{{r.status?'公开':'已隐藏'}}</el-tag></div><p>{{r.content}}</p><div v-if="r.reports?.length" class="merchant-reply"><b>用户举报记录</b><p v-for="(report,i) in r.reports" :key="i">{{report.status?'已处理':'待处理'}} · {{report.reason}}</p></div><div class="review-images"><el-image v-for="i in r.images" :key="i.id" :src="i.image_url" :preview-src-list="r.images.map(i=>i.image_url)" fit="cover"/></div><div class="merchant-reply" v-if="r.reply">商家回复：{{r.reply}}</div><div class="row-between"><small>{{date(r.create_time)}} · 订单 #{{r.order_id}}</small><div><button class="text-button" @click="run(()=>reply(r))">回复</button><button class="text-button muted" @click="run(()=>moderate(r))">{{r.status?'隐藏违规评价':'恢复展示'}}</button></div></div></article><p class="empty" v-if="!data.total">还没有用户评价。</p></template><template v-else-if="section==='revenue'"><div class="revenue-totals"><span>期间模拟收款 <b>¥{{yuan(data.totals?.paid)}}</b></span><span>期间成功退款 <b>¥{{yuan(data.totals?.refunded)}}</b></span><span>期间净流入 <b>¥{{yuan(Number(data.totals?.paid||0)-Number(data.totals?.refunded||0))}}</b></span></div><p class="subtle">期间汇总按支付及退款各自发生时间计算；下表按支付时间筛选，单笔净收款减去该订单累计成功退款。</p><el-table :data="data.items"><el-table-column prop="payment_no" label="模拟支付流水" min-width="180" show-overflow-tooltip/><el-table-column label="收款" width="110"><template #default="{row}">¥{{yuan(row.payment_amount)}}</template></el-table-column><el-table-column label="累计退款" width="110"><template #default="{row}">¥{{yuan(row.refunded)}}</template></el-table-column><el-table-column label="单笔净收款" width="120"><template #default="{row}">¥{{yuan(row.net)}}</template></el-table-column><el-table-column label="支付时间" width="170"><template #default="{row}">{{date(row.pay_time)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><button class="text-button" @click="selectedOrder=row.order_id">订单详情</button></template></el-table-column></el-table></template><template v-else-if="section==='users'"><el-table :data="data.items"><el-table-column prop="nickname" label="昵称"/><el-table-column prop="username" label="账号"/><el-table-column prop="phone" label="手机号" min-width="130"/><el-table-column prop="order_count" label="订单数" width="85"/><el-table-column label="净消费" width="110"><template #default="{row}">¥{{yuan(row.consumption)}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status?'success':'danger'">{{row.status?'正常':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="140"><template #default="{row}"><button class="text-button" @click="run(()=>userDetail(row))">详情</button><button class="text-button muted" @click="run(()=>userStatus(row))">{{row.status?'禁用':'恢复'}}</button></template></el-table-column></el-table></template><template v-else-if="section==='images'"><p class="subtle">支持JPG / PNG / WEBP，每张最多5MB。引用中的图片禁止删除，历史订单图片会保留。</p><el-table :data="data.items"><el-table-column label="预览" width="100"><template #default="{row}"><el-image style="width:60px;height:60px" :src="row.url" :preview-src-list="[row.url]" fit="cover"/></template></el-table-column><el-table-column prop="purpose" label="用途" width="100"/><el-table-column prop="url" label="图片地址" min-width="250"/><el-table-column label="上传时间" width="175"><template #default="{row}">{{date(row.create_time)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><button class="text-button muted" @click="run(async()=>{await ElMessageBox.confirm('仅可删除未被业务记录引用的图片。','删除闲置图片');await api.delete('/admin/media/'+row.id);await load()})">删除闲置图片</button></template></el-table-column></el-table></template><template v-else-if="section==='logs'"><el-table :data="data.items"><el-table-column prop="operator_id" label="操作人ID" width="100"/><el-table-column prop="action" label="操作" width="140"/><el-table-column prop="target_id" label="关联ID" width="100"/><el-table-column prop="reason" label="处理依据" min-width="230"/><el-table-column label="时间" width="180"><template #default="{row}">{{date(row.create_time)}}</template></el-table-column></el-table></template><Pager :page="page" :total="data.total" @change="v=>{page=v;run(load)}"/></div><footer class="admin-footer">花礼 FLEUR · 用心经营每一份美好 <span>Vue 3 · Spring Boot</span></footer></div></div><el-dialog v-model="productOpen" :title="product.id?'编辑鲜花商品':'新增鲜花商品'" width="740px" align-center><form class="stack-form" @submit.prevent="run(saveProduct)"><div class="form-two"><label>商品名称<input v-model="product.name" required maxlength="100"/></label><label>商品分类<select v-model="product.category_id" required><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><div class="form-three"><label>售价 / 元<input type="number" min="0.01" step="0.01" v-model="product.price" required/></label><label>{{product.id?'库存（通过库存管理调整）':'初始库存'}}<input type="number" min="0" max="1000000" step="1" v-model="product.stock" :disabled="!!product.id" required/></label><label>预警阈值<input type="number" min="0" max="1000000" v-model="product.warning_stock" required/></label></div><label>花束规格<input v-model="product.specification" required maxlength="200" placeholder="花材、数量与包装"/></label><label>商品介绍<textarea v-model="product.description" maxlength="6000" rows="3"/></label><label>封面图（每个商品一张）<div class="cover-editor"><img :src="product.cover" alt="商品封面预览"/><input type="file" accept="image/jpeg,image/png,image/webp" @change="run(()=>productPhotos($event,true))"/></div></label><label>详情图片（最多9张，可调整顺序）<input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="run(()=>productPhotos($event,false))"/></label><div class="product-upload-grid"><div v-for="(url,i) in product.images" :key="i"><img :src="url" alt="商品详情图片"/><div><button type="button" class="text-button" @click="moveImage(i,-1)">前移</button><button type="button" class="text-button" @click="moveImage(i,1)">后移</button><button type="button" class="text-button muted" @click="product.cover=url">设封面</button><button type="button" class="text-button muted" @click="product.images.splice(i,1)">移除</button></div></div></div><label>销售状态<select v-model="product.status"><option :value="0">下架（草稿）</option><option :value="1">上架</option></select></label><p class="subtle">图片移除后，可在图片管理中清理未引用文件；历史订单引用的图片会保留。</p><button class="btn primary" :disabled="busy">{{busy?'正在处理…':'保存商品'}}</button></form></el-dialog><el-dialog v-model="stockOpen" title="调整可售库存" width="480px"><form class="stack-form" @submit.prevent="run(saveStock)"><h3>{{stockForm.name}}</h3><p>当前可售库存：{{stockForm.current}}</p><label>操作类型<select v-model="stockForm.type"><option value="add">增加库存 / 入库</option><option value="reduce">减少库存 / 出库</option><option value="adjust">设为实际可售数量</option></select></label><label>数量<input type="number" min="0" max="1000000" step="1" v-model="stockForm.quantity" required/></label><label>调整说明<textarea v-model="stockForm.remark" required maxlength="255" rows="3"/></label><button class="btn primary" :disabled="busy">保存调整并记录日志</button></form></el-dialog><el-dialog :model-value="!!selectedOrder" @close="selectedOrder=null" title="订单详情与处理" width="780px" destroy-on-close align-center><OrderPanel v-if="selectedOrder" :id="selectedOrder" admin @changed="run(load)"/></el-dialog><el-dialog :model-value="!!selectedUser" @close="selectedUser=null" title="用户详情" width="720px"><template v-if="selectedUser"><h3>{{selectedUser.nickname}} · {{selectedUser.username}}</h3><p>手机号 {{selectedUser.phone||'未填写'}} · 注册于 {{date(selectedUser.create_time)}}</p><h4>最近50条订单（完整列表可在订单管理查询）</h4><el-table :data="selectedUser.orders.items"><el-table-column prop="order_no" label="订单编号" show-overflow-tooltip/><el-table-column label="金额" width="110"><template #default="{row}">¥{{yuan(row.total)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><button class="text-button" @click="selectedOrder=row.id">查看订单</button></template></el-table-column></el-table></template></el-dialog></div></template>

